import { Component, ElementRef, EventEmitter, Input, Output, ViewChild, AfterViewInit, OnChanges, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
    selector: 'app-rich-text-editor',
    standalone: true,
    imports: [CommonModule],
    template: `
    <div class="flex flex-col border border-[#ccc] rounded-md overflow-hidden bg-white shadow-sm w-full">
      
      <!-- Toolbar -->
      <div *ngIf="showToolbar" class="flex items-center gap-0.5 px-2 py-1.5 border-b border-[#e6e6e6] bg-white overflow-x-auto no-scrollbar">
        <!-- Paste -->
        <button (click)="execCommand('paste')" class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]" title="Paste">
           <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect width="8" height="4" x="8" y="2" rx="1" ry="1"/><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/></svg>
        </button>
        
        <div class="w-px h-6 bg-[#e6e6e6] mx-1"></div>

        <!-- Font Size (Simple Dropdown Mimic) -->
        <div class="relative group">
            <button class="flex items-center gap-1.5 px-2 py-1 hover:bg-[#f5f5f5] rounded text-sm cursor-pointer transition-colors">
                <span class="text-[#262626] font-medium">{{ fontSize }}</span>
                <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" class="text-[#666]" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>
            </button>
            <div class="absolute top-full left-0 hidden group-hover:block bg-white border border-[#262626] shadow-lg rounded-[4px] z-10 min-w-[60px]">
                <div *ngFor="let size of ['14', '16', '18', '20']" 
                     (click)="setFontSize(size)"
                     class="px-3 py-1.5 hover:bg-[#e7f8fb] cursor-pointer text-sm text-[#262626]">
                     {{ size }}
                </div>
            </div>
        </div>

        <div class="w-px h-6 bg-[#e6e6e6] mx-1"></div>

        <!-- Bold -->
        <button (click)="execCommand('bold')" 
                [class.bg-[#e7f8fb]]="isBold" [class.text-[#007a91]]="isBold"
                class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M14 12a4 4 0 0 0 0-8H6v8"/><path d="M15 20a4 4 0 0 0 0-8H6v8Z"/></svg>
        </button>

        <!-- Italic -->
        <button (click)="execCommand('italic')" 
                [class.bg-[#e7f8fb]]="isItalic" [class.text-[#007a91]]="isItalic"
                class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><line x1="19" x2="10" y1="4" y2="4"/><line x1="14" x2="5" y1="20" y2="20"/><line x1="15" x2="9" y1="4" y2="20"/></svg>
        </button>

        <!-- Underline -->
        <button (click)="execCommand('underline')" 
                [class.bg-[#e7f8fb]]="isUnderline" [class.text-[#007a91]]="isUnderline"
                class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M6 4v6a6 6 0 0 0 12 0V4"/><line x1="4" x2="20" y1="20" y2="20"/></svg>
        </button>

        <!-- Strikethrough -->
        <button (click)="execCommand('strikeThrough')" 
                [class.bg-[#e7f8fb]]="isStrikethrough" [class.text-[#007a91]]="isStrikethrough"
                class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M16 4H9a3 3 0 0 0-2.83 4"/><path d="M14 12a4 4 0 0 1 0 8H6"/><line x1="4" x2="20" y1="12" y2="12"/></svg>
        </button>

        <div class="w-px h-6 bg-[#e6e6e6] mx-1"></div>

        <!-- Lists -->
        <button (click)="execCommand('insertUnorderedList')" class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><line x1="8" x2="21" y1="6" y2="6"/><line x1="8" x2="21" y1="12" y2="12"/><line x1="8" x2="21" y1="18" y2="18"/><line x1="3" x2="3.01" y1="6" y2="6"/><line x1="3" x2="3.01" y1="12" y2="12"/><line x1="3" x2="3.01" y1="18" y2="18"/></svg>
        </button>
        <button (click)="execCommand('insertOrderedList')" class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><line x1="10" x2="21" y1="6" y2="6"/><line x1="10" x2="21" y1="12" y2="12"/><line x1="10" x2="21" y1="18" y2="18"/><path d="M4 6h1v4"/><path d="M4 10h2"/><path d="M6 18H4c0-1 2-2 2-3s-1-1.5-2-1"/></svg>
        </button>

        <div class="w-px h-6 bg-[#e6e6e6] mx-1"></div>

        <!-- Color Palette -->
        <div class="relative group">
            <button class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
                <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" [style.color]="textColor !== '#000000' ? textColor : undefined"><circle cx="13.5" cy="6.5" r=".5"/><circle cx="17.5" cy="10.5" r=".5"/><circle cx="8.5" cy="7.5" r=".5"/><circle cx="6.5" cy="12.5" r=".5"/><path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10c.926 0 1.648-.746 1.648-1.688 0-.437-.18-.835-.437-1.125-.29-.289-.438-.652-.438-1.125a1.64 1.64 0 0 1 1.668-1.668h1.996c3.051 0 5.555-2.503 5.555-5.554C21.965 6.012 17.461 2 12 2z"/></svg>
            </button>
            <div class="absolute top-full left-0 hidden group-hover:grid grid-cols-4 gap-1 bg-white border border-[#262626] shadow-lg rounded-[4px] z-10 min-w-[120px] p-1">
                 <div *ngFor="let color of ['#000000', '#007a91', '#e2001a', '#262626', '#666666', '#ffffff', '#ff0000', '#00ff00', '#0000ff', '#ffff00']"
                      (click)="setTextColor(color)"
                      class="w-6 h-6 rounded border border-[#e6e6e6] cursor-pointer hover:scale-110 transition-transform"
                      [style.background-color]="color">
                 </div>
            </div>
        </div>

        <!-- Highlight -->
        <button (click)="execCommand('hiliteColor', highlightColor)" class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
           <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="m9 11-6 6v3h9l3-3"/><path d="m22 2-7 7 1 1 7-7"/><path d="m17 7 4 4"/></svg>
        </button>

        <div class="w-px h-6 bg-[#e6e6e6] mx-1"></div>

        <!-- Link -->
        <button (click)="promptLink()" class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>
        </button>

        <!-- Attachment (Paperclip) -->
        <button class="p-1.5 hover:bg-[#f5f5f5] rounded transition-colors text-[#262626]">
           <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57A4 4 0 1 1 18 8.84l-8.59 8.57a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg>
        </button>

      </div>

      <!-- Editor Area -->
      <div #editor
           contentEditable="true"
           class="w-full px-4 py-[10px] bg-white focus:outline-none transition-colors composer-scrollbar overflow-y-auto rich-text-content"
           [style.min-height]="showToolbar ? '100px' : '44px'"
           [style.max-height]="maxHeight"
           (input)="onInput()"
           (focus)="onFocus()"
           (blur)="onBlur()"
           (keydown)="onKeyDown($event)">
      </div>

      <!-- Placeholder -->
      <div *ngIf="isEmpty && !isFocused" 
           class="absolute left-4 top-[10px] text-[#666] pointer-events-none select-none z-10"
           [style.top]="showToolbar ? '52px' : '10px'">
          {{ placeholder }}
      </div>

    </div>
  `
})
export class RichTextEditorComponent implements AfterViewInit {
    @Input() placeholder: string = 'Type your message...';
    @Input() content: string = '';
    @Input() showToolbar: boolean = false;
    @Input() maxHeight: string = '200px';
    @Output() contentChange = new EventEmitter<string>();
    @Output() enterPressed = new EventEmitter<void>();

    @ViewChild('editor') editorRef!: ElementRef<HTMLDivElement>;

    fontSize = '14';
    textColor = '#000000';
    highlightColor = '#ffff00';

    isBold = false;
    isItalic = false;
    isUnderline = false;
    isStrikethrough = false;

    isFocused = false;

    get isEmpty(): boolean {
        const html = this.editorRef?.nativeElement?.innerHTML || '';
        return !html || html === '<br>' || html === '<div><br></div>';
    }

    ngAfterViewInit() {
        if (this.content) {
            this.editorRef.nativeElement.innerHTML = this.content;
        }
    }

    onInput() {
        this.contentChange.emit(this.editorRef.nativeElement.innerHTML);
        this.checkActiveStyles();
    }

    onFocus() {
        this.isFocused = true;
        this.showToolbar = true; // Show toolbar on focus usually
    }

    onBlur() {
        setTimeout(() => {
            this.isFocused = false;
            // Optional: hide toolbar on blur if empty? user preference. Keeping it simple.
        }, 200);
    }

    onKeyDown(event: KeyboardEvent) {
        if (event.key === 'Enter' && !event.shiftKey) {
            event.preventDefault();
            this.enterPressed.emit();
        }
    }

    execCommand(command: string, value: string = '') {
        this.editorRef.nativeElement.focus();

        // Polyfill or standard command map
        let finalCmd = command;
        if (command === 'hiliteColor' && !document.queryCommandSupported('hiliteColor')) {
            finalCmd = 'backColor';
        }

        document.execCommand(finalCmd, false, value);
        this.onInput();
    }

    setFontSize(size: string) {
        this.fontSize = size;
        const sizeMap: Record<string, string> = { '14': '1', '16': '2', '18': '3', '20': '4' };
        this.execCommand('fontSize', sizeMap[size] || '1');
    }

    setTextColor(color: string) {
        this.textColor = color;
        this.execCommand('foreColor', color);
    }

    promptLink() {
        const url = prompt('Enter URL:');
        if (url) this.execCommand('createLink', url);
    }

    checkActiveStyles() {
        this.isBold = document.queryCommandState('bold');
        this.isItalic = document.queryCommandState('italic');
        this.isUnderline = document.queryCommandState('underline');
        this.isStrikethrough = document.queryCommandState('strikeThrough');
    }

    public clear() {
        if (this.editorRef) {
            this.editorRef.nativeElement.innerHTML = '';
            this.onInput();
        }
    }

    public focus() {
        this.editorRef?.nativeElement?.focus();
    }
}
